/* Card set: World Cities (generated from the approved roster-final.csv by the World Cities build, schema per tools/csv-to-set.js).
   (world-cities.js exceeds the comfortable push size, so the remaining cards live in
   world-cities-additions.js, which must stay directly after 'world-cities.js' in sets/manifest.js.) */
CardSets.register({"id":"world-cities","name":"World Cities","code":"CITY","description":"420 cards of skylines and cityscapes — great capitals, harbour cities, desert and mountain towns, and the ancient cities that started it all.","theme":{"primary":"#2e4057","secondary":"#e8873a","artBackground":"#eef1f5","artFit":"cover"},"pack":{"name":"World Cities Pack","emblem":"🌆","skin":"world-cities"},"cards":[{"name":"New York City","rarity":"chase","id":"new-york-city","subtitle":"United States","details":"Manhattan's skyline rises between the Hudson and East Rivers, a dense forest of towers anchored by the Empire State and Chrysler Buildings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lower_Manhattan_from_Brooklyn_May_2015_panorama.jpg?width=1024"},{"name":"Paris","rarity":"chase","id":"paris","subtitle":"France","details":"France's capital on the Seine, famed for Haussmann boulevards, the Eiffel Tower, Gothic Notre-Dame and grand museums gathered along the river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paris_Night.jpg?width=1024"},{"name":"London","rarity":"chase","id":"london","subtitle":"United Kingdom","details":"Capital of the United Kingdom on the River Thames, blending the Tower, Westminster and St Paul's with glass towers rising over old boroughs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/City_of_London_skyline_from_London_City_Hall_-_Oct_2008_-_Aligned.jpg?width=1024"},{"name":"Tokyo","rarity":"chase","id":"tokyo","subtitle":"Japan","details":"Japan's capital spreads around Tokyo Bay, blending neon-lit districts and Shinkansen hubs with quiet shrines, gardens, and the Skytree on its skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Minato_City%2C_Tokyo%2C_Japan.jpg?width=1024"},{"name":"Rome","rarity":"chase","id":"rome","subtitle":"Italy","details":"Italy's capital on the Tiber, where the Colosseum, Roman Forum and St Peter's Basilica stand among domes, piazze and ochre rooftops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_Rome_view_from_Via_San_Lucio.jpg?width=1024"},{"name":"Sydney","rarity":"chase","id":"sydney","subtitle":"Australia","details":"Harbour city founded as a British penal colony in 1788, wrapped around a vast natural harbour and famed for its sail-roofed opera house and steel arch bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20of%20Harbour%20-%20Sydney%20-%20Australia%20%2811215561286%29.jpg?width=1024"},{"name":"Rio de Janeiro","rarity":"chase","id":"rio-de-janeiro","subtitle":"Brazil","details":"Guanabara Bay, Sugarloaf and Corcovado frame a city spread between granite peaks, curved beaches and the Atlantic in a natural amphitheatre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rio_de_Janeiro_skyline_and_Sugarloaf_Mountain_at_sunset%2C_Brazil_3.jpg?width=1024"},{"name":"Hong Kong","rarity":"chase","id":"hong-kong","subtitle":"China","details":"A harbour city of steep hills and dense towers, where ferries cross Victoria Harbour between Hong Kong Island and the Kowloon peninsula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hong_Kong_Skyline_viewed_from_Victoria_Peak.jpg?width=1024"},{"name":"Istanbul","rarity":"chase","id":"istanbul","subtitle":"Turkey","details":"Straddling the Bosphorus between two continents, this city layers Byzantine domes, Ottoman minarets, and busy ferries over hills above the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Galata_Tower_-_Turkey_-_Istanbul_City_-_Tourist_attractions_-_Monument_06.jpg?width=1024"},{"name":"Cairo","rarity":"chase","id":"cairo","subtitle":"Egypt","details":"Egypt's capital spreads along the Nile, where medieval minarets and the Cairo Tower rise over one of the largest urban landscapes in Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cairo%20skyline%20panorama.jpg?width=1024"},{"name":"Madrid","rarity":"legendary","id":"madrid","subtitle":"Spain","details":"Spain's high-plateau capital, built around the Puerta del Sol and Gran Vía, with the Prado, Retiro Park and lively plazas at its heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madrid_cathedral_2020_-_view_from_the_dome.jpg?width=1024"},{"name":"Berlin","rarity":"legendary","id":"berlin","subtitle":"Germany","details":"Germany's capital on the Spree, where the Brandenburg Gate, Museum Island and the Fernsehturm tower mark layers of a reunified city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Berlin_Mitte_June_2023_01.jpg?width=1024"},{"name":"Vienna","rarity":"legendary","id":"vienna","subtitle":"Austria","details":"Austria's capital on the Danube, an imperial showcase of Ringstrasse palaces, the Hofburg and St Stephen's Cathedral at its core.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vienna_Austria_Skyline_Aerial,_October_2024.jpg?width=1024"},{"name":"Amsterdam","rarity":"legendary","id":"amsterdam","subtitle":"Netherlands","details":"Dutch capital laced with concentric canals and gabled houses, centred on Dam Square, the Rijksmuseum and rings of tree-lined waterways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canal_in_Jordaan,_Amsterdam_(9258952020).jpg?width=1024"},{"name":"Barcelona","rarity":"legendary","id":"barcelona","subtitle":"Spain","details":"Catalan capital on the Mediterranean, famed for Gaudí's Sagrada Família and Park Güell above the grid of the Eixample district.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barcelona_skyline_panorama_(6248341915).jpg?width=1024"},{"name":"Prague","rarity":"legendary","id":"prague","subtitle":"Czechia","details":"Czech capital on the Vltava, crowned by its castle and crossed by the Charles Bridge, with spires rising over a preserved old town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prague_Panorama_-_Oct_2010.jpg?width=1024"},{"name":"Budapest","rarity":"legendary","id":"budapest","subtitle":"Hungary","details":"Hungary's capital split by the Danube into Buda and Pest, linked by the Chain Bridge beneath the Parliament and Castle Hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Budapest_skyline_from_Gell%C3%A9rt_Hill_(6).jpg?width=1024"},{"name":"Athens","rarity":"legendary","id":"athens","subtitle":"Greece","details":"Greece's capital beneath the Acropolis and Parthenon, where classical ruins rise over white neighbourhoods spilling toward the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Athens_Acropolis_at_Daybreak.jpg?width=1024"},{"name":"Lisbon","rarity":"legendary","id":"lisbon","subtitle":"Portugal","details":"Portugal's capital spread over hills above the Tagus, known for yellow trams, tiled facades, the Belém Tower and Alfama's lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alfama_Rooftops_and_Tagus_River_View,_Lisbon_(54733828355).jpg?width=1024"},{"name":"Singapore","rarity":"legendary","id":"singapore","subtitle":"Singapore","details":"An island city at the tip of the Malay Peninsula, famed for its harbour, futuristic Marina Bay skyline, supertrees, and spotless garden districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Singapore_%28SG%29%2C_Marina_Bay_--_2019_--_4439-48.jpg?width=1024"},{"name":"Bangkok","rarity":"legendary","id":"bangkok","subtitle":"Thailand","details":"Thailand's capital spreads along the Chao Phraya River, mixing gilded temple spires and canal boats with glass towers, markets, and street food stalls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bangkok_City_Panorama_July_2019.jpg?width=1024"},{"name":"Beijing","rarity":"legendary","id":"beijing","subtitle":"China","details":"China's capital pairs vast imperial landmarks — the Forbidden City and Temple of Heaven — with ring roads, hutong lanes, and a modern CBD skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Beijing_CBD_with_B-5906_approaching_%2820211016171955%29.jpg?width=1024"},{"name":"Shanghai","rarity":"legendary","id":"shanghai","subtitle":"China","details":"Built along the Huangpu River, this port city faces its futuristic Pudong towers across the water from the historic Bund's colonial-era facades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pudong_night_skyline_viewed_from_the_Bund_in_Shanghai_%2841199899084%29.jpg?width=1024"},{"name":"Seoul","rarity":"legendary","id":"seoul","subtitle":"South Korea","details":"South Korea's capital sits in a bowl of granite mountains along the Han River, layering royal palaces among dense, neon-lit tower districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Han_River_Seoul_skyline_Pixabay_1214950.jpg?width=1024"},{"name":"Dubai","rarity":"legendary","id":"dubai","subtitle":"United Arab Emirates","details":"A desert port turned vertical city on the Gulf, where the Burj Khalifa rises over marina towers, old creek dhows, and man-made island lagoons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dubai_Skyline_%2825500263365%29.jpg?width=1024"},{"name":"Kyoto","rarity":"legendary","id":"kyoto","subtitle":"Japan","details":"Japan's old imperial capital preserves wooden machiya streets, Zen gardens, and over a thousand temples and shrines beneath wooded eastern hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kyoto_Blick_vom_Schrein_Fushimi-Inari-taisha_auf_Kyoto_3.jpg?width=1024"},{"name":"Taipei","rarity":"legendary","id":"taipei","subtitle":"Taiwan","details":"Ringed by green mountains and hot-spring valleys, this basin city is watched over by Taipei 101 and threaded by night markets and temple streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taipei_Skyline_2016.jpg?width=1024"},{"name":"Kuala Lumpur","rarity":"legendary","id":"kuala-lumpur","subtitle":"Malaysia","details":"Malaysia's capital grew from a tin-mining camp at a muddy river junction into a skyline crowned by the twin Petronas Towers and leafy suburbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Twins_SE_Asia_2019_%2849171985716%29.jpg?width=1024"},{"name":"Los Angeles","rarity":"legendary","id":"los-angeles","subtitle":"United States","details":"Downtown's towers stand against the San Gabriel Mountains, ringed by the freeways and palm-lined boulevards of a sprawling coastal basin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SR_110_south_Academy_Road_exit_from_Elysian_Park_2.jpg?width=1024"},{"name":"Chicago","rarity":"legendary","id":"chicago","subtitle":"United States","details":"Towers line the Chicago River and Lake Michigan shore, where the steel-frame skyscraper was pioneered after the Great Fire of 1871.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_de_Chicago_desde_el_centro,_Illinois,_Estados_Unidos,_2012-10-20,_DD_06.jpg?width=1024"},{"name":"San Francisco","rarity":"legendary","id":"san-francisco","subtitle":"United States","details":"Hills roll down to the bay in a compact skyline, anchored by the Transamerica Pyramid and wrapped, famously, in summer fog.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/San_Francisco_from_Twin_Peaks_September_2013_panorama_5_edit.jpg?width=1024"},{"name":"Toronto","rarity":"legendary","id":"toronto","subtitle":"Canada","details":"The CN Tower rises over a dense downtown on Lake Ontario's north shore, one of the tallest freestanding structures in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sunset_Toronto_Skyline_Panorama_Crop_from_Snake_Island.jpg?width=1024"},{"name":"Vancouver","rarity":"legendary","id":"vancouver","subtitle":"Canada","details":"Glass towers cluster on a downtown peninsula between Burrard Inlet and English Bay, with the Coast Mountains walling the horizon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vancouver_dusk_pano.jpg?width=1024"},{"name":"Boston","rarity":"legendary","id":"boston","subtitle":"United States","details":"One of America's oldest cities pairs a colonial street plan and red-brick rows with a modern tower core across the Charles River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boston_skyline_from_Longfellow_Bridge_September_2017_panorama_2.jpg?width=1024"},{"name":"Buenos Aires","rarity":"legendary","id":"buenos-aires","subtitle":"Argentina","details":"A grid of grand avenues on the Río de la Plata, famed for the café culture, tango halls and Parisian-style facades of its many barrios.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Puerto_Madero_Panorama.jpg?width=1024"},{"name":"Mexico City","rarity":"legendary","id":"mexico-city","subtitle":"Mexico","details":"Built on the Aztec capital Tenochtitlan in a high mountain valley, layering pre-Hispanic ruins, colonial churches and vast modern avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ciudad.de.Mexico.City.Distrito.Federal.DF.Paseo.Reforma.Skyline.jpg?width=1024"},{"name":"São Paulo","rarity":"legendary","id":"sao-paulo","subtitle":"Brazil","details":"A vast inland plateau metropolis of endless tower blocks, anchored by Avenida Paulista and fed by waves of immigration from every continent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PaulistaPanorama.jpg?width=1024"},{"name":"Cape Town","rarity":"legendary","id":"cape-town","subtitle":"South Africa","details":"South Africa's Mother City fills the bowl beneath flat-topped Table Mountain, between the Atlantic Ocean and steep sandstone peaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Town%20panorama%20%2840425029403%29.jpg?width=1024"},{"name":"Marrakech","rarity":"legendary","id":"marrakech","subtitle":"Morocco","details":"Morocco's Red City glows with rose-coloured walls and palm groves, its medina lanes unfolding beneath the snow-dusted Atlas Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marrakech%20skyline%20view.jpg?width=1024"},{"name":"Melbourne","rarity":"legendary","id":"melbourne","subtitle":"Australia","details":"Victoria's capital on the Yarra River, founded in 1835 and enriched by gold rushes, famed for laneways, Victorian grandeur and great sporting arenas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melbourne%20Skyline%20from%20Rialto%20Crop%20-%20Nov%202008.jpg?width=1024"},{"name":"Dublin","rarity":"epic","id":"dublin","subtitle":"Ireland","details":"Ireland's capital on the River Liffey, centred on Trinity College, Temple Bar and Georgian squares south of the river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dublin_-_O'Connell_Bridge_-_20150918203526.jpg?width=1024"},{"name":"Edinburgh","rarity":"epic","id":"edinburgh","subtitle":"United Kingdom","details":"Scotland's capital beneath its castle rock, split between the medieval Old Town ridge and the Georgian terraces of the New Town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh_cityscapes_-_aerial_-_panorama_-_2025-04-19_01.jpg?width=1024"},{"name":"Stockholm","rarity":"epic","id":"stockholm","subtitle":"Sweden","details":"Sweden's capital spread across fourteen islands where Lake Mälaren meets the Baltic, with Gamla Stan's ochre lanes at its centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stockholm_Skyline_(15732915419).jpg?width=1024"},{"name":"Copenhagen","rarity":"epic","id":"copenhagen","subtitle":"Denmark","details":"Denmark's capital on Zealand's harbour, known for Nyhavn's coloured houses, the Little Mermaid and the towers of Christiansborg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen_Lakes,_Denmark_-_K%C3%B8benhavn_S%C3%B8erne,_Danmark_-_Copenhagen_Skyline_Cityscape_-_Taken_with_Fotodiox_Rhinocam_-_Mamiya_80mm_f2.8_lens,_super_high_resolution_-_Flickr_-_Kristoffer_Trolle.jpg?width=1024"},{"name":"Oslo","rarity":"epic","id":"oslo","subtitle":"Norway","details":"Norway's capital at the head of the Oslofjord, framed by forested hills and marked by its Opera House sloping into the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oslo_Panorama_Winter.jpg?width=1024"},{"name":"Helsinki","rarity":"epic","id":"helsinki","subtitle":"Finland","details":"Finland's capital on Baltic inlets, built around its white cathedral and Senate Square, with islands scattered offshore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Helsinki_skyline_banner.jpg?width=1024"},{"name":"Warsaw","rarity":"epic","id":"warsaw","subtitle":"Poland","details":"Poland's capital on the Vistula, its Old Town rebuilt after wartime destruction beside the Palace of Culture and modern towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Warsaw,_Poland.jpg?width=1024"},{"name":"Zurich","rarity":"epic","id":"zurich","subtitle":"Switzerland","details":"Switzerland's largest city on Lake Zurich and the Limmat, an old town of guild houses beneath church towers and Alpine views.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%BCrich_view_Quaibr%C3%BCcke_20200702.jpg?width=1024"},{"name":"Munich","rarity":"epic","id":"munich","subtitle":"Germany","details":"Bavarian capital on the Isar, centred on Marienplatz and its Glockenspiel, famed for beer halls, the English Garden and Oktoberfest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vista_panor%C3%A1mica_desde_Olympiapark,_M%C3%BAnich,_Alemania_2012-04-28,_DD_03.JPG?width=1024"},{"name":"Florence","rarity":"epic","id":"florence","subtitle":"Italy","details":"Tuscan city on the Arno, cradle of the Renaissance, crowned by Brunelleschi's dome and crossed by the shop-lined Ponte Vecchio.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_Florence_from_Piazzale_Michelangelo.jpg?width=1024"},{"name":"Venice","rarity":"epic","id":"venice","subtitle":"Italy","details":"Italian city built on lagoon islands, threaded by canals to St Mark's Square, its basilica and the Doge's Palace on the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hazy_aerial_panorama_of_Venice_rooftops_toward_the_lagoon_at_sunset_(2023).jpg?width=1024"},{"name":"Brussels","rarity":"epic","id":"brussels","subtitle":"Belgium","details":"Belgium's capital, centred on the gilded Grand-Place, home to the European Union quarter and the Atomium to the north.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Night_skyline_above_Rue_de_la_Fourche,_Brussels,_2013.jpg?width=1024"},{"name":"Osaka","rarity":"epic","id":"osaka","subtitle":"Japan","details":"Japan's merchant city built its identity on canals, street food, and Dotonbori's neon signs, with a rebuilt castle rising over its business districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Osaka_Skyline_from_Abeno_Harukas_20260505_115626_UTC%2B9_75_mm.jpg?width=1024"},{"name":"Hanoi","rarity":"epic","id":"hanoi","subtitle":"Vietnam","details":"Vietnam's capital wraps around lakes and tree-lined boulevards, its Old Quarter's narrow shophouse streets trading beside French colonial facades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama-hanoi.jpg?width=1024"},{"name":"Ho Chi Minh City","rarity":"epic","id":"ho-chi-minh-city","subtitle":"Vietnam","details":"Vietnam's largest city pulses along the Saigon River, where French colonial landmarks stand among motorbike-filled avenues and new glass towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ho_Chi_Minh_City_Skyline.jpg?width=1024"},{"name":"Jakarta","rarity":"epic","id":"jakarta","subtitle":"Indonesia","details":"Indonesia's capital spreads across a low coastal plain on Java, mixing Dutch colonial Kota Tua, vast malls, and a fast-rising central skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jakarta_skyline_at_night._Business_District_area_at_Jalan_Rasuna_Said%2C_South_Jakarta%2C_as_seen_from_Kuningan_District%2C_South_Jakarta%2C_Indonesia.jpg?width=1024"},{"name":"Manila","rarity":"epic","id":"manila","subtitle":"Philippines","details":"The Philippines' capital curves around Manila Bay, pairing the walled Spanish old town of Intramuros with the high-rise districts of Makati and BGC.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_from_Grand_Hyatt_Manila_overlooking_Bonifacio_Global_City_and_Makati_skylines_at_sunset.jpg?width=1024"},{"name":"Mumbai","rarity":"epic","id":"mumbai","subtitle":"India","details":"India's film and finance capital stretches along a natural harbour on the Arabian Sea, from colonial Gothic landmarks to the towers of Bandra Kurla.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Worli_Panorama_25_May_2013.jpg?width=1024"},{"name":"Delhi","rarity":"epic","id":"delhi","subtitle":"India","details":"One city, many eras: Mughal tombs and Old Delhi's bazaars in the north, the broad ceremonial avenues of New Delhi laid out to the south.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_at_Rajiv_Chowk.JPG?width=1024"},{"name":"Kathmandu","rarity":"epic","id":"kathmandu","subtitle":"Nepal","details":"Nepal's capital fills a Himalayan foothill valley with tiered pagoda temples, medieval durbar squares, and stupas ringed by prayer flags.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nepal_-_Kathmandu_-_Roofscape_1_%28493491524%29.jpg?width=1024"},{"name":"Colombo","rarity":"epic","id":"colombo","subtitle":"Sri Lanka","details":"Sri Lanka's ocean-facing commercial capital mixes a colonial fort district and seaside Galle Face Green with a rapidly rising port-city skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ColomboSkyline_-_November_2017_%281%29.jpg?width=1024"},{"name":"Abu Dhabi","rarity":"epic","id":"abu-dhabi","subtitle":"United Arab Emirates","details":"The Emirates' capital spreads across Gulf islands, joining the white domes of Sheikh Zayed Grand Mosque with corniche towers and mangrove channels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abu_Dhabi_Skyline_fron_Corniche_Rd.JPG?width=1024"},{"name":"Doha","rarity":"epic","id":"doha","subtitle":"Qatar","details":"Qatar's capital arcs around a crescent bay, where the dhow harbour and Souq Waqif face the sculptural glass towers of the West Bay skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/West_Bay_Skyline%2C_Doha%2C_State_of_Qatar.jpg?width=1024"},{"name":"Riyadh","rarity":"epic","id":"riyadh","subtitle":"Saudi Arabia","details":"Saudi Arabia's capital rises from the Najd plateau, its Kingdom Centre and Al Faisaliah towers landmarking a grid of broad desert boulevards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Riyadh_North_Skyline_.jpg?width=1024"},{"name":"Seattle","rarity":"epic","id":"seattle","subtitle":"United States","details":"The Space Needle punctuates a skyline between Puget Sound and Lake Washington, framed by Mount Rainier on clear days to the south.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Space_Needle_and_Seattle_skyline_from_Kerry_Park_with_waxing_gibbous_moon,_27_June_2026.jpg?width=1024"},{"name":"Denver","rarity":"epic","id":"denver","subtitle":"United States","details":"A mile above sea level, downtown's towers stand on the high plains with the snow-capped Front Range of the Rockies filling the west.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Denver_Panorama_(cropped).png?width=1024"},{"name":"Miami","rarity":"epic","id":"miami","subtitle":"United States","details":"High-rises crowd the Biscayne Bay shoreline, a gateway city between the Americas with a tropical skyline of white and glass towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Miami,_Florida_skyline.jpg?width=1024"},{"name":"New Orleans","rarity":"epic","id":"new-orleans","subtitle":"United States","details":"Founded on a bend of the Mississippi in 1718, the city mixes French Quarter balconies and garden districts with a compact riverfront core.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New_Orleans_skyline-02.jpg?width=1024"},{"name":"Nashville","rarity":"epic","id":"nashville","subtitle":"United States","details":"The AT&T Building's twin spires crown a downtown on the Cumberland River, in the city long known as the capital of country music.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nashville_skyline_2009.jpg?width=1024"},{"name":"Austin","rarity":"epic","id":"austin","subtitle":"United States","details":"Texas's capital gathers along the Colorado River, where a fast-growing tower core rises behind live-music halls and oak-shaded streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Austin_Texas_skyline,_December_2023_-_Night.jpg?width=1024"},{"name":"Houston","rarity":"epic","id":"houston","subtitle":"United States","details":"The largest Texas skyline spreads across a flat coastal plain, built on oil, its great ship channel port, and the Johnson Space Center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buildings-city-houston-skyline-1870617.jpg?width=1024"},{"name":"Dallas","rarity":"epic","id":"dallas","subtitle":"United States","details":"Reunion Tower's glowing sphere marks a skyline of glass towers on the Trinity River prairie, a center of banking, trade, and rail history.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dallas_Skyline_at_Dusk.jpg?width=1024"},{"name":"Montreal","rarity":"epic","id":"montreal","subtitle":"Canada","details":"Mount Royal overlooks an old port city on the St. Lawrence River, where French colonial streets meet a downtown of modern towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Montreal_Twilight_Panorama_2006.jpg?width=1024"},{"name":"Honolulu","rarity":"epic","id":"honolulu","subtitle":"United States","details":"Waikiki's hotels line a crescent beach beneath Diamond Head, the volcanic tuff crater that defines Hawaii's capital shoreline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Honolulu-03.jpg?width=1024"},{"name":"Lima","rarity":"epic","id":"lima","subtitle":"Peru","details":"A desert coastal capital founded by Pizarro, where colonial balconies overlook Pacific cliffs and pre-Inca pyramids rise among the districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Costa_Verde_%26_Highrise_Buildings_-_Lima.jpg?width=1024"},{"name":"Bogotá","rarity":"epic","id":"bogota","subtitle":"Colombia","details":"A high Andean capital pressed against forested eastern hills, known for its gold museum, colonial La Candelaria and Sunday ciclovía streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_del_Centro_Internacional_de_Bogot%C3%A1.jpg?width=1024"},{"name":"Santiago","rarity":"epic","id":"santiago","subtitle":"Chile","details":"Set in a valley beneath the snow-capped Andes, with Cerro San Cristóbal rising over its barrios and vineyards on the city's dry eastern edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Santiago%2C_Chile.jpg?width=1024"},{"name":"Havana","rarity":"epic","id":"havana","subtitle":"Cuba","details":"A harbour capital of Spanish colonial fortresses, sea-battered Malecón and streets of weathered pastel facades and 1950s American cars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Havanna_Panorama.jpg?width=1024"},{"name":"Johannesburg","rarity":"epic","id":"johannesburg","subtitle":"South Africa","details":"South Africa's largest city grew from Witwatersrand gold reefs into a highveld metropolis of jacaranda-lined suburbs and mine dumps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Johannesburg%20skyline%202017.jpg?width=1024"},{"name":"Nairobi","rarity":"epic","id":"nairobi","subtitle":"Kenya","details":"Kenya's capital pairs a modern skyline with Nairobi National Park, where giraffes graze against a backdrop of downtown towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nairobi%20Skyline%20Savannah%20Kenya%20May19%20R1600687.jpg?width=1024"},{"name":"Lagos","rarity":"epic","id":"lagos","subtitle":"Nigeria","details":"Nigeria's great port city spreads across islands and mainland shores of the Lagos Lagoon, a sprawling Atlantic-facing commercial giant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lagos%20skyline.jpg?width=1024"},{"name":"Casablanca","rarity":"epic","id":"casablanca","subtitle":"Morocco","details":"Morocco's Atlantic port is crowned by the Hassan II Mosque, whose minaret soars over the ocean at the edge of a whitewashed cityscape.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Casablanca%20banner.jpg?width=1024"},{"name":"Auckland","rarity":"epic","id":"auckland","subtitle":"New Zealand","details":"New Zealand's largest city, spread across an isthmus between two harbours on a field of volcanic cones, watched over by the slender Sky Tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Auckland%20Skyline%20as%20seen%20from%20Devonport%2020100128%203.jpg?width=1024"},{"name":"Brisbane","rarity":"epic","id":"brisbane","subtitle":"Australia","details":"Queensland's capital, founded as a penal settlement in 1824 on the winding Brisbane River, known for subtropical gardens and timber Queenslander houses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brisbane%20skyline%20from%20Kangaroo%20Point.jpg?width=1024"},{"name":"Pompeii","rarity":"epic","id":"pompeii","subtitle":"Italy","details":"Roman city near Naples buried in hours by Vesuvius in AD 79; its excavated streets, baths, theatres and frescoed villas preserve a whole urban world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Pompeii%20and%20Mount%20Vesuvius%20%28view%20from%20the%20southeast%29.jpg?width=1024"},{"name":"Petra","rarity":"epic","id":"petra","subtitle":"Jordan","details":"Nabataean caravan capital carved into rose-red sandstone canyons by the first century BC, its royal tombs and temples hidden behind a narrow gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petra%20%2C%20Al-Khazneh%202.jpg?width=1024"},{"name":"Seville","rarity":"rare","id":"seville","subtitle":"Spain","details":"Andalusian capital on the Guadalquivir, home to a vast Gothic cathedral, the Giralda tower and the tilework of Plaza de España.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seville_skyline_(49160110067).jpg?width=1024"},{"name":"Valencia","rarity":"rare","id":"valencia","subtitle":"Spain","details":"Spanish Mediterranean port on the Turia, mixing a Gothic old town with Calatrava's white City of Arts and Sciences.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_Val%C3%A8ncia.jpg?width=1024"},{"name":"Krakow","rarity":"rare","id":"krakow","subtitle":"Poland","details":"Polish city on the Vistula centred on Europe's great market square, with Wawel Castle above and the towers of St Mary's Basilica.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Krakow_-_Wawel_from_Vistula_-_4.jpg?width=1024"},{"name":"Dubrovnik","rarity":"rare","id":"dubrovnik","subtitle":"Croatia","details":"Croatian walled city on the Adriatic, its marble streets and terracotta roofs ringed by massive ramparts above a clear blue sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_dubrovnik_pano_-_edit1.jpg?width=1024"},{"name":"Reykjavik","rarity":"rare","id":"reykjavik","subtitle":"Iceland","details":"Iceland's capital on Faxaflói bay, a spread of colourful roofs beneath Hallgrímskirkja's sweeping concrete spire and Mount Esja.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HDR_Reykjavik_skyline_(10139777493).jpg?width=1024"},{"name":"Gothenburg","rarity":"rare","id":"gothenburg","subtitle":"Sweden","details":"Swedish west-coast port on the Göta älv, a city of canals, trams and the Haga district's wooden houses and broad avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Karlatornet_along_with_Gothenburg_skyline..jpg?width=1024"},{"name":"Tallinn","rarity":"rare","id":"tallinn","subtitle":"Estonia","details":"Estonia's capital on the Baltic, its medieval Old Town of towers and red roofs enclosed by walls above a busy ferry harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Old_town_of_Tallinn_06-03-2012.jpg?width=1024"},{"name":"Riga","rarity":"rare","id":"riga","subtitle":"Latvia","details":"Latvia's capital on the Daugava, famed for Europe's richest spread of Art Nouveau facades around a Hanseatic old town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline,_Riga.jpg?width=1024"},{"name":"Vilnius","rarity":"rare","id":"vilnius","subtitle":"Lithuania","details":"Lithuania's capital at the Neris and Vilnia rivers, a baroque old town of church spires overlooked by Gediminas Tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vilnius_Modern_Skyline,_Lithuania_-_Diliff.jpg?width=1024"},{"name":"Bratislava","rarity":"rare","id":"bratislava","subtitle":"Slovakia","details":"Slovakia's capital on the Danube, watched over by its four-towered castle, with a compact old town of palaces and squares.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Danube_in_Bratislava_skyline,_New_Bridge,_Bratislava_Castle_in_Bratislava,_Bratislava_I_District.jpg?width=1024"},{"name":"Ljubljana","rarity":"rare","id":"ljubljana","subtitle":"Slovenia","details":"Slovenia's capital on the Ljubljanica river, centred on a hilltop castle, Triple Bridge and Plečnik's elegant embankments.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ljubljana_panorama_3.jpg?width=1024"},{"name":"Zagreb","rarity":"rare","id":"zagreb","subtitle":"Croatia","details":"Croatia's capital between Mount Medvednica and the Sava, split between the medieval Upper Town and a grand 19th-century Lower Town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zagreb_2015_-_Zagreba%C4%8Dka_katedrala_-_pogled_s_Gornjeg_Grada_(Zagreb_Cathedral_-_view_from_Upper_Town)_-_panoramio.jpg?width=1024"},{"name":"Belgrade","rarity":"rare","id":"belgrade","subtitle":"Serbia","details":"Serbia's capital at the meeting of the Sava and Danube, watched over by the Kalemegdan fortress and its riverside promenades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_Belgrade_from_Kalemegdan_fortress.jpg?width=1024"},{"name":"Bucharest","rarity":"rare","id":"bucharest","subtitle":"Romania","details":"Romania's capital, known for the colossal Palace of the Parliament, Belle Époque boulevards and the lanes of its Old Town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bucharest-Skyline-01.jpg?width=1024"},{"name":"Sofia","rarity":"rare","id":"sofia","subtitle":"Bulgaria","details":"Bulgaria's capital in a mountain-ringed basin, centred on the golden domes of the Alexander Nevsky Cathedral and Roman Serdica ruins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sofia_skyline_3.jpg?width=1024"},{"name":"Naples","rarity":"rare","id":"naples","subtitle":"Italy","details":"Italian port beneath Mount Vesuvius on its great bay, a dense old city of castles, churches and the birthplace of pizza.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Naples_from_the_Castello_Sant_Elmo_with_Abbazia_San_Martino.jpg?width=1024"},{"name":"Milan","rarity":"rare","id":"milan","subtitle":"Italy","details":"Lombardy's capital, crowned by the marble spires of its Duomo and the glass dome of the Galleria Vittorio Emanuele II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Full_Milan_skyline_from_Duomo_roof.jpg?width=1024"},{"name":"Porto","rarity":"rare","id":"porto","subtitle":"Portugal","details":"Portuguese city tumbling down granite hills to the Douro, famed for port wine cellars across the river in Vila Nova de Gaia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centro_Hist%C3%B3rico_de_Porto_por_Rodrigo_Tetsuo_Argenton_(03).jpg?width=1024"},{"name":"Chiang Mai","rarity":"rare","id":"chiang-mai","subtitle":"Thailand","details":"Northern Thailand's old capital sits within moats and partial walls near Doi Suthep mountain, filled with Lanna temples and night bazaars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chiang_Mai_Panorama_from_Doi_Suthep_Lookout_%282014-08-08%29.jpg?width=1024"},{"name":"George Town","rarity":"rare","id":"george-town","subtitle":"Malaysia","details":"Penang's capital preserves rows of painted shophouses, clan jetties, and street-food lanes in a UNESCO-listed old town under Penang Hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_George_Town_from_the_air%2C_Dec_2023.jpg?width=1024"},{"name":"Da Nang","rarity":"rare","id":"da-nang","subtitle":"Vietnam","details":"A central Vietnam port between the Han River and the South China Sea, known for its dragon bridge, long beaches, and the Marble Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Han_River_Bridge_in_Vietnam_Night_View.jpg?width=1024"},{"name":"Hue","rarity":"rare","id":"hue","subtitle":"Vietnam","details":"Vietnam's former imperial capital lines the Perfume River with a vast citadel, royal tombs, and pagodas shaded by pine-covered hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_the_Citadel_of_Hu%E1%BA%BF.jpg?width=1024"},{"name":"Busan","rarity":"rare","id":"busan","subtitle":"South Korea","details":"South Korea's great port climbs hills around busy harbours and beaches, home to Jagalchi fish market and the colourful Gamcheon village lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_the_Haeundae_Skyline.png?width=800"},{"name":"Nagoya","rarity":"rare","id":"nagoya","subtitle":"Japan","details":"Japan's manufacturing heartland city between Tokyo and Osaka, rebuilt around wide boulevards, a castle with golden shachihoko, and a busy port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nagoya_Station_-_View_from_the_Main_Building_in_Nagoya_Campus_of_Aichi_University_2022-6-29.jpg?width=1024"},{"name":"Sapporo","rarity":"rare","id":"sapporo","subtitle":"Japan","details":"Hokkaido's capital is laid out on a neat grid beneath mountains, famous for its snow festival sculptures, clock tower, and Odori Park boulevard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sapporo_City_Skyline20230312.jpg?width=1024"},{"name":"Fukuoka","rarity":"rare","id":"fukuoka","subtitle":"Japan","details":"Kyushu's largest city grew around Hakata Bay's port and rivers, known for open-air yatai food stalls and the ruins of Fukuoka Castle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Views_of_Hilton_Fukuoka_Seahawk_and_Fukuoka_Dome_from_Seaside_Momochi_Beach.jpg?width=1024"},{"name":"Guangzhou","rarity":"rare","id":"guangzhou","subtitle":"China","details":"The historic Canton port on the Pearl River pairs Lingnan arcades and old Shamian Island with the soaring Canton Tower and Zhujiang New Town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guangzhou_Banner.jpg?width=1024"},{"name":"Shenzhen","rarity":"rare","id":"shenzhen","subtitle":"China","details":"A fishing-region turned megacity beside Hong Kong, built in decades into a forest of tech towers, theme parks, and green mountain parks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Commercial_area_of_futian_to_east2020.jpg?width=1024"},{"name":"Chengdu","rarity":"rare","id":"chengdu","subtitle":"China","details":"Sichuan's capital is famed for teahouses, spicy hotpot, and its giant panda breeding base, set on a fertile plain beneath distant snow peaks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chengdu_skyline_June_2017.jpg?width=1024"},{"name":"Xi'an","rarity":"rare","id":"xi-an","subtitle":"China","details":"One of China's oldest capitals, guarded by a complete Ming city wall and the buried Terracotta Army of the first emperor, Qin Shi Huang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bell_Tower_during_Sunset_in_Xi%27an%2C_Jun_21_2023.jpg?width=1024"},{"name":"Hangzhou","rarity":"rare","id":"hangzhou","subtitle":"China","details":"Celebrated for West Lake's pagodas, causeways, and tea hills, this former Song capital blends garden scenery with a modern bay-side skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/West_Lake_IMG_8757_hangzhou_panorama.jpg?width=1024"},{"name":"Bangalore","rarity":"rare","id":"bangalore","subtitle":"India","details":"India's garden city and tech hub sits high on the Deccan plateau, mixing colonial parks and palaces with glass campuses and lake-filled suburbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bangalore_Panorama.jpg?width=1024"},{"name":"Chennai","rarity":"rare","id":"chennai","subtitle":"India","details":"Tamil Nadu's capital stretches along the Coromandel Coast, home to Marina Beach, Kapaleeshwarar Temple's carved tower, and Fort St. George.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chennai_Skyline.jpg?width=1024"},{"name":"Tel Aviv","rarity":"rare","id":"tel-aviv","subtitle":"Israel","details":"A Mediterranean beach city of white Bauhaus buildings, boulevards, and markets, growing south from the ancient port lanes of Old Jaffa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PikiWiki_Israel_58105_jaffa_-_old_city.jpg?width=1024"},{"name":"Muscat","rarity":"rare","id":"muscat","subtitle":"Oman","details":"Oman's capital threads between rocky mountains and the sea, its low white buildings, Muttrah corniche, and twin forts guarding the old harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_the_coastline_of_Muttrah.jpg?width=1024"},{"name":"Tbilisi","rarity":"rare","id":"tbilisi","subtitle":"Georgia","details":"Georgia's capital climbs the Mtkvari River gorge, where balconied old-town lanes, sulphur bath domes, and Narikala Fortress watch over the city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2014_Tbilisi%2C_Widoki_z_Twierdzy_Narikala_%2836%29.jpg?width=1024"},{"name":"Atlanta","rarity":"rare","id":"atlanta","subtitle":"United States","details":"Peachtree streets run through green hills to a two-cluster skyline, in the rail hub that grew into the Southeast's leading metropolis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atlanta_skyline_from_Jackson_Street_Bridge_2020.jpg?width=1024"},{"name":"Phoenix","rarity":"rare","id":"phoenix","subtitle":"United States","details":"A desert downtown rises from the Salt River Valley, framed by Camelback Mountain and ringed by ranges in the Sonoran Desert.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Phoenix_Skyline_Lights.jpg?width=1024"},{"name":"San Diego","rarity":"rare","id":"san-diego","subtitle":"United States","details":"Towers step down to a sheltered Pacific harbor near the Mexican border, in a bay city shaped by its navy port and mild coastal climate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St_Diego_Skyline_Panorama_2013.jpg?width=1024"},{"name":"Portland","rarity":"rare","id":"portland-oregon","subtitle":"United States","details":"Bridges stitch the Willamette River banks together below Mount Hood's snowy cone, in a city known for roses, rain, and evergreen hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portland_from_Pittock_Mansion_October_2019_panorama_2.jpg?width=1024"},{"name":"Philadelphia","rarity":"rare","id":"philadelphia","subtitle":"United States","details":"William Penn's statue crowns City Hall beneath modern glass towers, on the grid Penn planned between the Delaware and Schuylkill Rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philadelphia_from_South_Street_Bridge_July_2016_panorama_2.jpg?width=1024"},{"name":"Pittsburgh","rarity":"rare","id":"pittsburgh","subtitle":"United States","details":"Three rivers meet at the Golden Triangle, where inclines climb Mount Washington for the classic view over downtown's towers and bridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pittsburgh_skyline_panorama_daytime.jpg?width=1024"},{"name":"St. Louis","rarity":"rare","id":"st-louis","subtitle":"United States","details":"The Gateway Arch soars 630 feet over the Mississippi riverfront, marking the historic jumping-off point for westward expansion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St_Louis_night_expblend.jpg?width=1024"},{"name":"Kansas City","rarity":"rare","id":"kansas-city","subtitle":"United States","details":"Fountains and boulevards spread across bluffs above the Missouri River, in a jazz and barbecue city straddling the Kansas-Missouri line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kansas_City_MO_Skyline_14July2008vcroped.jpg?width=1024"},{"name":"Minneapolis","rarity":"rare","id":"minneapolis","subtitle":"United States","details":"Downtown towers rise beside the Mississippi's St. Anthony Falls, linked by an enclosed skyway system against the long northern winters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Minneapolis_skyline_across_the_Mississippi_River.jpg?width=1024"},{"name":"Detroit","rarity":"rare","id":"detroit","subtitle":"United States","details":"Art Deco towers line the Detroit River across from Canada, in the city that put the world on wheels as the heart of the auto industry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Detroit_Skyline_(123143197).jpeg?width=1024"},{"name":"Baltimore","rarity":"rare","id":"baltimore","subtitle":"United States","details":"The Inner Harbor wraps a working port on the Patapsco River, where brick rowhouses climb hills above one of America's oldest seaports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baltimore_Inner_Harbor_Skyline_Night_Panorama.jpg?width=1024"},{"name":"Charlotte","rarity":"rare","id":"charlotte","subtitle":"United States","details":"The Bank of America Corporate Center crowns Uptown, a banking skyline grown from a Carolina gold-rush crossroads into a finance hub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_of_Charlotte_2016.jpg?width=1024"},{"name":"Quebec City","rarity":"rare","id":"quebec-city","subtitle":"Canada","details":"The Château Frontenac towers over the walled old town above the St. Lawrence, behind the only surviving city walls in North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_Frontenac_after_a_freezing_rain_day_in_Quebec_city.jpg?width=1024"},{"name":"Las Vegas","rarity":"rare","id":"las-vegas","subtitle":"United States","details":"The Strip's themed resorts and glowing towers rise from the Mojave Desert floor, a neon skyline built on gaming and entertainment.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Las_Vegas_(Nevada,_USA),_The_Strip_--_2012_--_6232.jpg?width=1024"},{"name":"Quito","rarity":"rare","id":"quito","subtitle":"Ecuador","details":"One of the highest capitals on Earth, draped over Andean slopes with a remarkably preserved colonial old town of churches and plazas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vista_de_Quito_desde_El_Panecillo%2C_Ecuador%2C_2015-07-22%2C_DD_25-29_PAN.JPG?width=1024"},{"name":"Cusco","rarity":"rare","id":"cusco","subtitle":"Peru","details":"The Inca imperial capital, where precisely fitted stone walls still carry Spanish colonial buildings above narrow cobbled streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peru_-_Cusco_018_-_Plaza_de_Armas_panorama_%287084767603%29.jpg?width=1024"},{"name":"Cartagena","rarity":"rare","id":"cartagena","subtitle":"Colombia","details":"A walled Caribbean port of balconied colonial streets and fortresses, facing a modern tower skyline across the bay at Bocagrande.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Bocagrande_from_Bastion_Santiago_Apostol_CTG_11_2019_9822.jpg?width=1024"},{"name":"Panama City","rarity":"rare","id":"panama-city","subtitle":"Panama","details":"A Pacific tower skyline at the canal's southern mouth, contrasting with the colonial ruins of Panamá Viejo and the Casco Antiguo quarter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panama_City_Skyline_2015.jpg?width=1024"},{"name":"San José","rarity":"rare","id":"san-jose-costa-rica","subtitle":"Costa Rica","details":"Set in Costa Rica's Central Valley between volcanoes, a capital of coffee wealth, the gilt National Theatre and green mountain horizons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Costa_Rica_-_San_Jose_pano.jpg?width=1024"},{"name":"Santo Domingo","rarity":"rare","id":"santo-domingo","subtitle":"Dominican Republic","details":"The oldest European-founded city in the Americas, whose Zona Colonial holds the first cathedral, castle and hospital of the New World.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Santo_Domingo_Skyline.jpg?width=1024"},{"name":"Kingston","rarity":"rare","id":"kingston","subtitle":"Jamaica","details":"A capital wrapped around one of the world's great natural harbours, backed by the Blue Mountains and famed as the birthplace of reggae.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Kingston.jpg?width=1024"},{"name":"Accra","rarity":"rare","id":"accra","subtitle":"Ghana","details":"Ghana's capital stretches along the Gulf of Guinea, blending fishing beaches, the Black Star Gate and busy markets in Osu and Jamestown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20drone%20footage%20of%20Accra%20central%2C%20Ghana.jpg?width=1024"},{"name":"Dakar","rarity":"rare","id":"dakar","subtitle":"Senegal","details":"Senegal's capital occupies the Cap-Vert peninsula, the westernmost point of mainland Africa, ringed by Atlantic surf and fishing pirogues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dakar%20skyline%20da%20gor%C3%A8.jpg?width=1024"},{"name":"Addis Ababa","rarity":"rare","id":"addis-ababa","subtitle":"Ethiopia","details":"Ethiopia's capital climbs into the Entoto foothills at high altitude, a city of eucalyptus groves, coffee houses and broad avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Addis%20Ababa%20skyline.jpg?width=1024"},{"name":"Dar es Salaam","rarity":"rare","id":"dar-es-salaam","subtitle":"Tanzania","details":"Tanzania's harbour city curves around a natural port on the Indian Ocean, where dhows sail past a skyline of towers and colonial facades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dar%20Es%20Salaam%20Skyline%20%2834011488084%29.jpg?width=1024"},{"name":"Tunis","rarity":"rare","id":"tunis","subtitle":"Tunisia","details":"Tunisia's capital lines a lake channel to the Mediterranean, its medina of souks and mosques contrasting with French-era avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20de%20Tunis%2001.jpg?width=1024"},{"name":"Algiers","rarity":"rare","id":"algiers","subtitle":"Algeria","details":"Algeria's capital cascades down hills to the Mediterranean in a white amphitheatre, earning its nickname Algiers the White.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alger-Gouvernement-General.jpg?width=1024"},{"name":"Fez","rarity":"rare","id":"fez","subtitle":"Morocco","details":"Morocco's spiritual heart holds Fes el Bali, a vast medieval medina of tanneries, madrasas and thousands of winding car-free lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fez%20Skyline%20%2852188883598%29.jpg?width=1024"},{"name":"Perth","rarity":"rare","id":"perth","subtitle":"Australia","details":"Western Australia's capital on the Swan River, founded in 1829 and among the world's most isolated big cities, framed by the bushland of Kings Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Perth%20%28AU%29%2C%20View%20from%20Kings%20Park%20--%202019%20--%200525-30.jpg?width=1024"},{"name":"Wellington","rarity":"rare","id":"wellington","subtitle":"New Zealand","details":"New Zealand's capital since 1865, a compact harbour city of steep streets and timber houses gathered around a broad bay at the North Island's tip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wellington%20and%20West%20from%20Mt%20Vic.jpg?width=1024"},{"name":"Hobart","rarity":"rare","id":"hobart","subtitle":"Australia","details":"Tasmania's capital, founded in 1804 on the Derwent estuary beneath kunanyi / Mount Wellington, among Australia's oldest cities and a gateway south.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hobart%20from%20Mount%20Wellington%20Panorama%201.jpg?width=1024"},{"name":"Babylon","rarity":"rare","id":"babylon","subtitle":"Iraq","details":"Great Mesopotamian capital on the Euphrates, seat of Hammurabi and Nebuchadnezzar II, famed for the Ishtar Gate, Processional Way and a towering ziggurat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/001125-Babylon-Iraq-IMG%208003-2.jpg?width=1024"},{"name":"Troy","rarity":"rare","id":"troy","subtitle":"Turkey","details":"Layered Bronze Age city guarding the Dardanelles at Hisarlik, where nine stacked settlements span three millennia of trade, craft and siege.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Troy%20archeological%20site%20%288708437345%29.jpg?width=1024"},{"name":"Ephesus","rarity":"rare","id":"ephesus","subtitle":"Turkey","details":"Greco-Roman harbour city in Anatolia, home to the Temple of Artemis and the Library of Celsus, its marble streets lined with theatres and terraced houses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Looking%20down%20the%20Street%20of%20Curetes%20%2816314212482%29.jpg?width=1024"},{"name":"Palmyra","rarity":"rare","id":"palmyra","subtitle":"Syria","details":"Oasis caravan city in the Syrian desert grown rich on Silk Road trade, famed for its colonnaded avenue, great temples and tower tombs in golden stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palmyra%2C%20Syria%2C%20Ruins.jpg?width=1024"},{"name":"Leptis Magna","rarity":"rare","id":"leptis-magna","subtitle":"Libya","details":"Phoenician-founded port in Libya enlarged by its native son, emperor Septimius Severus, among the finest preserved Roman cities on the Mediterranean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Theatre%2C%20Leptis%20Magna%2C%20Libya.jpg?width=1024"},{"name":"Hamburg","rarity":"uncommon","id":"hamburg","subtitle":"Germany","details":"Germany's great port city on the Elbe, Hamburg mixes red-brick warehouse districts, a vast working harbour and more bridges than Venice or Amsterdam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hamburg_Skyline_from_Steinwerder_%2815149198567%29.jpg?width=1024"},{"name":"Frankfurt","rarity":"uncommon","id":"frankfurt","subtitle":"Germany","details":"Frankfurt pairs a medieval old town and Römer square with one of Europe's few true skyscraper skylines, rising over the broad River Main in Hesse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_Frankfurt_am_Main_2015.jpg?width=1024"},{"name":"Cologne","rarity":"uncommon","id":"cologne","subtitle":"Germany","details":"Cologne spreads along the Rhine beneath its twin-spired Gothic cathedral, one of Germany's oldest cities and a Rhineland centre of art and carnival.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cologne_-_Panoramic_Image_of_the_old_town_at_dusk.jpg?width=1024"},{"name":"Rotterdam","rarity":"uncommon","id":"rotterdam","subtitle":"Netherlands","details":"Rotterdam, Europe's great seaport on the Maas, rebuilt itself with bold modern towers, cube houses and the sweeping Erasmus Bridge after wartime bombing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%2C_Rotterdam.jpg?width=1024"},{"name":"Antwerp","rarity":"uncommon","id":"antwerp","subtitle":"Belgium","details":"Antwerp on the Scheldt blends a Gothic cathedral, Rubens' Baroque city and the diamond quarter with one of the largest ports in Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antwerp_Skyline_%2891424213%29.jpeg?width=1024"},{"name":"Bruges","rarity":"uncommon","id":"bruges","subtitle":"Belgium","details":"Bruges is a preserved medieval Flemish city of canals, stepped gables and the Belfry tower, once a wealthy trading port of the Hanseatic age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama-view-Bruges.jpg?width=1024"},{"name":"Salzburg","rarity":"uncommon","id":"salzburg","subtitle":"Austria","details":"Salzburg spreads beneath Hohensalzburg Fortress on the Salzach, a Baroque city of domes and spires famed as the birthplace of Mozart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salzburg_Altstadt_Panorama_20170409_02.jpg?width=1024"},{"name":"Innsbruck","rarity":"uncommon","id":"innsbruck","subtitle":"Austria","details":"Innsbruck fills a narrow Inn valley beneath the Nordkette Alps, its old town marked by the Golden Roof and pastel houses along the river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Innsbruck_Panorama_Nordkette_3.jpg?width=1024"},{"name":"Granada","rarity":"uncommon","id":"granada","subtitle":"Spain","details":"Granada lies at the foot of Spain's Sierra Nevada, where the Alhambra palace crowns a hill above Moorish Albaicín lanes and Renaissance streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Granada_Panorama_from_Alhambra_2009.jpg?width=1024"},{"name":"Bilbao","rarity":"uncommon","id":"bilbao","subtitle":"Spain","details":"Bilbao wraps around the Nervión estuary in the Basque Country, where the titanium Guggenheim Museum anchors a revived industrial riverfront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bilbao_city_skyline_from_Etxebarria_Park_%2826779657642%29.jpg?width=1024"},{"name":"Nice","rarity":"uncommon","id":"nice","subtitle":"France","details":"Nice curves along the Baie des Anges on the French Riviera, its Promenade des Anglais fronting pebble beaches below Castle Hill and Belle Époque hotels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nice_from_Castle_Hill_01.jpg?width=1024"},{"name":"Lyon","rarity":"uncommon","id":"lyon","subtitle":"France","details":"Lyon stands where the Rhône and Saône meet, a city of Roman ruins, Renaissance traboule passages and silk-weavers' hills in eastern France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Lyon_depuis_Fourvi%C3%A8re_sous_averses_%282012%29.JPG?width=1024"},{"name":"Marseille","rarity":"uncommon","id":"marseille","subtitle":"France","details":"Marseille, France's great Mediterranean port, rings its old harbour with limestone hills, the basilica of Notre-Dame de la Garde watching from above.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline_Marseille_Fort_Saint-Jean.jpg?width=1024"},{"name":"Bordeaux","rarity":"uncommon","id":"bordeaux","subtitle":"France","details":"Bordeaux lines the crescent of the Garonne with grand 18th-century stone facades, a famous wine trade and the reflecting Miroir d'eau plaza.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bordeaux_-_Vue_d%27avion_-_View_from_plane_-_Picture_image_photography_garonne_pont_bridge_chaban_delmas_pont_de_pierre_d%27aquitaine_saint_jean_%288683043366%29.jpg?width=1024"},{"name":"Malmo","rarity":"uncommon","id":"malmo","subtitle":"Sweden","details":"Malmö faces Copenhagen across the Øresund, a Swedish port city of old squares and the twisting Turning Torso tower on its redeveloped waterfront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malm%C3%B6_Central_Station%2C_2023_Nov_15.jpg?width=1024"},{"name":"Aarhus","rarity":"uncommon","id":"aarhus","subtitle":"Denmark","details":"Aarhus, Denmark's second city, pairs a Viking-age core and an open-air old town with a modern harbour on Aarhus Bay beneath its cathedral spire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aarhus_skyline_seen_from_Aarhus_%C3%98.jpg?width=1024"},{"name":"York","rarity":"uncommon","id":"york","subtitle":"United Kingdom","details":"York in northern England keeps its medieval walls, the great Minster cathedral and the Shambles' overhanging timber shops above Roman and Viking layers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/York_Minster_from_the_city_walls_-_geograph.org.uk_-_7551008.jpg?width=1024"},{"name":"Bath","rarity":"uncommon","id":"bath","subtitle":"United Kingdom","details":"Bath is built of honey-coloured stone in Georgian crescents around Roman baths fed by natural hot springs in England's Avon valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bath%2C_Somerset_Panorama_-_April_2011.jpg?width=1024"},{"name":"Oxford","rarity":"uncommon","id":"oxford","subtitle":"United Kingdom","details":"Oxford's dreaming spires rise over the Thames and Cherwell, where honey-stone colleges of its ancient university line medieval streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oxford_Skyline_-_geograph.org.uk_-_2918656.jpg?width=1024"},{"name":"Cambridge","rarity":"uncommon","id":"cambridge","subtitle":"United Kingdom","details":"Cambridge spreads along the River Cam, its Gothic chapels, courts and Backs lawns forming one of England's most storied university cities.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cambridge%2C_King%27s_College_and_the_Backs_-_geograph.org.uk_-_2540261.jpg?width=1024"},{"name":"Cardiff","rarity":"uncommon","id":"cardiff","subtitle":"United Kingdom","details":"Cardiff, capital of Wales, grew from a coal port on the Taff into a city of castles, arcades and a redeveloped bay on the Bristol Channel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cardiff_skyline_December_18%2C_2010.jpg?width=1024"},{"name":"Belfast","rarity":"uncommon","id":"belfast","subtitle":"United Kingdom","details":"Belfast sits at the head of Belfast Lough beneath Cave Hill, a linen and shipbuilding city where the Harland & Wolff cranes still mark the skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belfast_Skyline_%2811819773124%29.jpg?width=1024"},{"name":"Cork","rarity":"uncommon","id":"cork","subtitle":"Ireland","details":"Cork climbs steep lanes from the River Lee in southwest Ireland, a harbour city of markets, spires and colourful quays near the Atlantic coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial-View-Cork-City.jpg?width=1024"},{"name":"Galway","rarity":"uncommon","id":"galway","subtitle":"Ireland","details":"Galway faces the Atlantic on Ireland's west coast, a harbour city of medieval lanes, buskers and festivals at the mouth of the River Corrib.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Galway_Panorama_%287061241087%29.jpg?width=1024"},{"name":"Bergen","rarity":"uncommon","id":"bergen","subtitle":"Norway","details":"Bergen is ringed by seven mountains and fjords on Norway's west coast, its Bryggen wharf of Hanseatic timber warehouses lining the harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_of_Bryggen%2C_Bergen.jpg?width=1024"},{"name":"Gdansk","rarity":"uncommon","id":"gdansk","subtitle":"Poland","details":"Gdańsk rebuilds its Hanseatic glory on the Baltic, with a crane-topped waterfront, amber shops and the tall gables of its Long Market.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hotel_Hanza_panorama_od_Mot%C5%82awy.jpg?width=1024"},{"name":"Thessaloniki","rarity":"uncommon","id":"thessaloniki","subtitle":"Greece","details":"Thessaloniki spreads along the Thermaic Gulf in Greek Macedonia, anchored by the White Tower and layered with Roman, Byzantine and Ottoman monuments.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_White_Tower_Lefkos_Pirgos_From_The_Nikis_Avenue_Leoforos_Nikis_On_The_Seafront_W_To_The_%28156815585%29.jpeg?width=1024"},{"name":"Valletta","rarity":"uncommon","id":"valletta","subtitle":"Malta","details":"Valletta crowns a peninsula between two harbours in Malta, a fortress capital of limestone bastions, Baroque churches and grid streets built by knights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Valletta_seen_from_Senglea%2C_Malta_%28PPL2-Enhanced%29_julesvernex2.jpg?width=1024"},{"name":"Hyderabad","rarity":"uncommon","id":"hyderabad","subtitle":"India","details":"Pearl City founded in 1591 on the Musi River, famed for the Charminar, Golconda Fort, biryani and a tech district nicknamed Cyberabad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Financial%20District%2C%20Hyderabad%20-%20Wide%20panoramic%20skyline%20view%20from%20Nanakramguda%20to%20Gachibowli.jpg?width=1024"},{"name":"Kolkata","rarity":"uncommon","id":"kolkata","subtitle":"India","details":"Former capital of British India on the Hooghly River, famed for the Howrah Bridge, colonial avenues, trams, book fairs and Durga Puja.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kolkata%20Skyline%20From%20Vidyasagar%20Seti%202.jpg?width=1024"},{"name":"Jaipur","rarity":"uncommon","id":"jaipur","subtitle":"India","details":"Rajasthan's Pink City, founded in 1727 with wide gridded avenues, rose-tinted facades, the Hawa Mahal and bazaars for gems and textiles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hawa%20Mahal%20skyline.jpg?width=1024"},{"name":"Udaipur","rarity":"uncommon","id":"udaipur","subtitle":"India","details":"The City of Lakes in Rajasthan, where white palaces and ghats ring Lake Pichola beneath the green ridges of the Aravalli Hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Udaipur%2C%20India%2C%20Skyline%20of%20Udaipur%20with%20Udaipur%20Palace.jpg?width=1024"},{"name":"Varanasi","rarity":"uncommon","id":"varanasi","subtitle":"India","details":"One of the world's oldest living cities, its stone ghats step down to the Ganges beside a labyrinth of temples and silk weavers' lanes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Varanasi%2C%20India%2C%20Boats%2C%20Ganges%20River.jpg?width=1024"},{"name":"Pune","rarity":"uncommon","id":"pune","subtitle":"India","details":"Maharashtra city beneath the Sahyadri hills, once a Maratha stronghold, known for the Aga Khan Palace, forts and old wada mansions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pune%20West%20skyline%20-%20March%202017.jpg?width=1024"},{"name":"Ahmedabad","rarity":"uncommon","id":"ahmedabad","subtitle":"India","details":"Gujarat's riverfront city on the Sabarmati, famed for its UNESCO-listed old town of pols, stepwells, textiles and Gandhi's ashram.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sabarmati%20riverfront%20and%20Atal%20Pedestrian%20Bridge%2005.jpg?width=1024"},{"name":"Isfahan","rarity":"uncommon","id":"isfahan","subtitle":"Iran","details":"Safavid jewel of Iran, built around the vast Naqsh-e Jahan Square with turquoise-tiled mosques, domes and vaulted bazaars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Naghshe%20Jahan%20Square%20Isfahan%20modified2.jpg?width=1024"},{"name":"Shiraz","rarity":"uncommon","id":"shiraz","subtitle":"Iran","details":"City of poets and gardens in southern Iran, home to the tombs of Hafez and Saadi, the pink-tiled Nasir al-Mulk Mosque and Persepolis nearby.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shiraz%20Panoramic%20view.jpg?width=1024"},{"name":"Yerevan","rarity":"uncommon","id":"yerevan","subtitle":"Armenia","details":"One of the world's oldest continuously inhabited cities, built of pink tuff stone beneath Mount Ararat, centred on Republic Square.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Ararat%20and%20the%20Yerevan%20skyline.jpg?width=1024"},{"name":"Baku","rarity":"uncommon","id":"baku","subtitle":"Azerbaijan","details":"Caspian port capital of Azerbaijan, where the walled Old City and Maiden Tower stand near the flame-shaped towers of the modern skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baku%20Skyline%20qiz%20qalasi.jpg?width=1024"},{"name":"Almaty","rarity":"uncommon","id":"almaty","subtitle":"Kazakhstan","details":"Kazakhstan's leafy former capital at the foot of the snowcapped Trans-Ili Alatau, lined with orchards, parks and wide Soviet avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Almaty%20Skyline.jpg?width=1024"},{"name":"Tashkent","rarity":"uncommon","id":"tashkent","subtitle":"Uzbekistan","details":"Silk Road crossroads and Uzbekistan's capital, blending Timurid monuments, the Chorsu Bazaar dome and broad Soviet-era avenues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Modern%20Tashkent.%20Skyline.jpg?width=1024"},{"name":"Samarkand","rarity":"uncommon","id":"samarkand","subtitle":"Uzbekistan","details":"Legendary Silk Road city in Uzbekistan, crowned by the mosaic-tiled Registan square and the soaring dome of Bibi-Khanym Mosque.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20the%20eastern%20Samarkand%20from%20the%20hill%20of%20the%20Afrasiyab%20settlement.jpg?width=1024"},{"name":"Bukhara","rarity":"uncommon","id":"bukhara","subtitle":"Uzbekistan","details":"Ancient Uzbek trading city of domed bazaars and madrasas, where the Kalyan Minaret has watched over caravan routes since 1127.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2012%20Bukhara%207515821196.jpg?width=1024"},{"name":"Ulaanbaatar","rarity":"uncommon","id":"ulaanbaatar","subtitle":"Mongolia","details":"Mongolia's high-altitude capital, where ger districts spread around Soviet blocks and Gandantegchinlen Monastery on the Tuul River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ulaanbaatar%20skyline.jpg?width=1024"},{"name":"Thimphu","rarity":"uncommon","id":"thimphu","subtitle":"Bhutan","details":"Bhutan's capital in a pine-clad Himalayan valley, a city without traffic lights, watched over by the great Tashichho Dzong fortress.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20view%20of%20Thimphu%20looking%20N%20from%20Talakha%20Gonpa%20-1.jpg?width=1024"},{"name":"Pokhara","rarity":"uncommon","id":"pokhara","subtitle":"Nepal","details":"Nepal's lakeside city beneath Machhapuchhre's fishtail peak, a gateway to the Annapurna trails along the shore of Phewa Lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20of%20Pokhara%20city%2C%20Nepal.jpg?width=1024"},{"name":"Luang Prabang","rarity":"uncommon","id":"luang-prabang","subtitle":"Laos","details":"Laos' royal city at the meeting of the Mekong and Nam Khan rivers, famed for gilded temples, French villas and dawn alms processions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mountains%20Mekong%20river%20and%20dwellings%20seen%20from%20Mount%20Phou%20Si%20at%20dusk%20in%20Luang%20Prabang%20Laos.jpg?width=1024"},{"name":"Yangon","rarity":"uncommon","id":"yangon","subtitle":"Myanmar","details":"Myanmar's garden city of lakes and colonial avenues, crowned by the golden Shwedagon Pagoda rising above a skyline of low rooftops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yangon%20Skyline%20from%20Olympic%20Tower.jpg?width=1024"},{"name":"Mandalay","rarity":"uncommon","id":"mandalay","subtitle":"Myanmar","details":"Myanmar's last royal capital on the Irrawaddy River, ringed by pagoda-topped hills and famed for crafts, monasteries and Mandalay Hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20panorama%20of%20Mandalay%20Palace%2C%20Myanmar%20%2816071710391%29.jpg?width=1024"},{"name":"Surabaya","rarity":"uncommon","id":"surabaya","subtitle":"Indonesia","details":"East Java's port city on the Madura Strait, a trading hub since Majapahit times, famed for the Suramadu Bridge and its old Arab quarter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Central%20Surabaya%20view%20taken%20from%20JW%20Marriott%20Surabaya%20%28cropped%29.jpg?width=1024"},{"name":"Yogyakarta","rarity":"uncommon","id":"yogyakarta","subtitle":"Indonesia","details":"Java's cultural heart near Mount Merapi, a sultan's city of batik, gamelan and silverwork, gateway to Borobudur and Prambanan temples.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malioboro%20Street%2C%20Yogyakarta.JPG?width=1024"},{"name":"Bandung","rarity":"uncommon","id":"bandung","subtitle":"Indonesia","details":"West Java highland city ringed by volcanoes and tea fields, famed for its Dutch art deco avenues, fashion outlets and cool mountain air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/East%20Bandung%20skyline.jpg?width=1024"},{"name":"Denpasar","rarity":"uncommon","id":"denpasar","subtitle":"Indonesia","details":"Bali's capital, a low-rise city of family temples, markets and museums near Sanur beach, gateway to the island's Hindu heartland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20to%20the%20south%20from%20the%20Bajra%20Sandhi%20Monument.jpg?width=1024"},{"name":"Cebu City","rarity":"uncommon","id":"cebu-city","subtitle":"Philippines","details":"The Philippines' oldest city, a busy Visayan port where Magellan's Cross and the Santo Niño basilica stand near a growing harbour skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cebu%20City%20skyline%2C%20CCLEX%20Bridge%2C%20Cebu%20Strait%20%28Cebu%20City%3B%2001-17-2025%29.jpg?width=1024"},{"name":"Kaohsiung","rarity":"uncommon","id":"kaohsiung","subtitle":"Taiwan","details":"Taiwan's great southern port, where container terminals and the Love River meet landmarks like the Lotus Pond pagodas and Pier-2 arts district.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kaohsiung%20Skyline%202014.jpg?width=1024"},{"name":"Kobe","rarity":"uncommon","id":"kobe","subtitle":"Japan","details":"Japanese port city squeezed between the Rokko Mountains and Osaka Bay, famed for its night skyline, Kitano foreign residences and beef.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kobe%20Skyline%20%26%20Berge.jpg?width=1024"},{"name":"Salt Lake City","rarity":"uncommon","id":"salt-lake-city","subtitle":"United States","details":"Utah's capital spreads across a valley floor beneath the Wasatch Range, its grid of wide streets centered on Temple Square and the state capitol hill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salt_Lake_City_-_July_16%2C_2011.jpg?width=1024"},{"name":"Albuquerque","rarity":"uncommon","id":"albuquerque","subtitle":"United States","details":"New Mexico's largest city stretches along the Rio Grande beneath the Sandia Mountains, where adobe architecture meets Route 66 neon in the high desert.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Albuquerque_Downtown_Sky.JPG?width=1024"},{"name":"Santa Fe","rarity":"uncommon","id":"santa-fe","subtitle":"United States","details":"The oldest state capital in the United States, Santa Fe gathers adobe buildings around a central plaza in the foothills of the Sangre de Cristo Range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Santa_Fe_downtown.jpg?width=1024"},{"name":"Boise","rarity":"uncommon","id":"boise","subtitle":"United States","details":"Idaho's capital sits on the Boise River at the edge of sagebrush foothills, a tree-lined downtown watched over by the sandstone state capitol dome.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boise_Downtown_Panoramic.jpg?width=1024"},{"name":"Reno","rarity":"uncommon","id":"reno","subtitle":"United States","details":"Nevada's 'Biggest Little City' spreads across the Truckee River valley at the foot of the Sierra Nevada, lit by casino marquees and mountain sunsets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Downtown_Reno%2C_Nevada_%2820948872664%29.jpg?width=1024"},{"name":"Sacramento","rarity":"uncommon","id":"sacramento","subtitle":"United States","details":"California's capital stands where the American and Sacramento rivers meet, its gold-domed capitol rising over a canopy of city trees and leveed streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sacramento%2C_CA_skyline.jpg?width=1024"},{"name":"San Jose","rarity":"uncommon","id":"san-jose-california","subtitle":"United States","details":"At the southern end of San Francisco Bay, San Jose grew from a Spanish pueblo and orchard country into the sprawling heart of Silicon Valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SAN_JOSE_CALIFORNIA_BAYAREA01.jpg?width=1024"},{"name":"Orlando","rarity":"uncommon","id":"orlando","subtitle":"United States","details":"Central Florida's lake-dotted hub grew around Lake Eola and a compact downtown, ringed by the resort corridors that made it a byword for theme parks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orlando%2C_Florida.jpg?width=1024"},{"name":"Tampa","rarity":"uncommon","id":"tampa","subtitle":"United States","details":"A Gulf Coast port on Tampa Bay, Tampa blends a modern riverfront skyline with the cigar-making heritage of Ybor City across the Hillsborough River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tampa_Florida_November_2013-3a.jpg?width=1024"},{"name":"Charleston","rarity":"uncommon","id":"charleston","subtitle":"United States","details":"South Carolina's harbor city preserves rows of pastel houses and church steeples on a peninsula where the Ashley and Cooper rivers meet the Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charleston_skyline_from_Charleston_Harbor.JPG?width=1024"},{"name":"Savannah","rarity":"uncommon","id":"savannah","subtitle":"United States","details":"Georgia's oldest city fans out from the Savannah River in a grid of leafy public squares, shaded by live oaks draped in Spanish moss.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Savannah_-_Talmadge_Memorial_Bridge.jpg?width=1024"}]});
